function inject_unit_test_related_values(Array $default_theme_options)
{
	$default_theme_options['side_panel_enabled'] = false;
	$default_theme_options['footer_spacing']['padding-top'] = '50px';
	$default_theme_options['footer_spacing']['padding-bottom'] = '0px';
	$default_theme_options['blog_list_sidebar_gap'] = '30';
	$default_theme_options['single_sidebar_gap'] = '30';
	$default_theme_options['page_title_height']['height'] = '400';
	$default_theme_options['page_title_padding']['padding-top'] = '50';
	$default_theme_options['single_padding_layout_3']['padding-top'] = '374';

	return $default_theme_options;
}

add_action('after_switch_theme', 'motto_get_default_option');
add_action('after_setup_theme', function() {
	$version = '1.0.3';
	if (get_option('motto_option_version') != $version) {
		motto_get_default_option();
		update_option('motto_option_version', $version);
	}
});

function motto_fonts_url()
{
	$font1 = esc_html_x( 'on', 'Poppins: on or off', 'motto' );
	$font2 = esc_html_x( 'on', 'Outfit: on or off', 'motto' );

    if ('off' !== $font1 || 'off' !== $font2) {
		$font_families = [];

		if ('off' !== $font1) $font_families[] = 'Poppins:400,500';
		if ('off' !== $font2) $font_families[] = 'Outfit:300,400,500,600,700';

		$query_args = [
			'family' => urlencode(implode('|', $font_families)),
			'subset' => urlencode('latin,latin-ext'),
		];

		$fonts_url = add_query_arg($query_args, 'https://fonts.googleapis.com/css');
	}

	return esc_url_raw($fonts_url ?? '');
}

add_action('admin_enqueue_scripts', function() {
	wp_enqueue_style(
		'editor-google-fonts',
		motto_fonts_url(),
		[],
		WGL_Globals::get_theme_version()
	);
});

if (!class_exists('WGL_Extensions_Core')) {
	add_action('wp_enqueue_scripts', function () {
		wp_enqueue_style(
			'motto-default-font',
			motto_fonts_url(),
			[],
			WGL_Globals::get_theme_version()
		);
	});
}
